//! Typed application bindings used for catalog admission and runtime calls.

use crate::runtime::{PluginStore, RuntimeComponent};
use wasmtime::{
    Store,
    component::{Instance, Linker},
};

#[doc(hidden)]
pub struct BindingExport {
    pub interface: &'static str,
    pub item: &'static str,
    pub signature: &'static str,
}

/// A generated binding role used for admission, host installation, and runtime calls.
///
/// Implementations are generated by [`crate::bindings!`].
#[doc(hidden)]
pub trait Binding<S: Send + Sync + 'static>: Sized + 'static {
    const WORLD: &'static str;
    const EXPORTS: &'static [BindingExport];
    const HOST_IMPORTS: &'static [&'static str];

    type Client<'runtime>
    where
        S: 'runtime;

    fn bind(store: &mut Store<PluginStore<S>>, instance: &Instance) -> anyhow::Result<Self>;

    fn install_host_import(
        interface: &str,
        linker: &mut Linker<PluginStore<S>>,
    ) -> anyhow::Result<()>;

    fn client<'runtime>(component: RuntimeComponent<'runtime, S, Self>) -> Self::Client<'runtime>
    where
        S: 'runtime;
}
